#include <vector>
#include <complex>
#include <algorithm>
#include <cstddef>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable mergesort:
    // 1) Split into chunks, sort each chunk by magnitude (sequential per chunk).
    // 2) Iteratively merge adjacent sorted runs in parallel into a temporary buffer.
    const int maxThreads = omp_get_max_threads();
    int T = maxThreads > 0 ? maxThreads : 1;
    if (static_cast<std::size_t>(T) > n) T = static_cast<int>(n);

    std::vector<std::complex<double>> tmp(n);

    auto mag2 = [](const std::complex<double>& z) -> double {
        // Compare by squared magnitude to avoid sqrt.
        const double a = z.real();
        const double b = z.imag();
        return a * a + b * b;
    };

    auto comp = [&](const std::complex<double>& a, const std::complex<double>& b) -> bool {
        return mag2(a) < mag2(b);
    };

    // Compute chunk boundaries [bounds[t], bounds[t+1])
    std::vector<std::size_t> bounds(static_cast<std::size_t>(T) + 1);
    for (int t = 0; t <= T; ++t) {
        bounds[static_cast<std::size_t>(t)] = (n * static_cast<std::size_t>(t)) / static_cast<std::size_t>(T);
    }

    // Sort chunks in parallel
    #pragma omp parallel for schedule(static)
    for (int t = 0; t < T; ++t) {
        const std::size_t lo = bounds[static_cast<std::size_t>(t)];
        const std::size_t hi = bounds[static_cast<std::size_t>(t + 1)];
        if (hi > lo) {
            std::stable_sort(x.begin() + static_cast<std::ptrdiff_t>(lo),
                             x.begin() + static_cast<std::ptrdiff_t>(hi),
                             comp);
        }
    }

    // Merge runs: width is run size; double each pass.
    // We alternate source/destination between x and tmp.
    bool srcIsX = true;
    for (std::size_t width = bounds[1] - bounds[0]; width < n; width *= 2) {
        // If initial width might be 0 (shouldn't if n>=2), handle gracefully.
        if (width == 0) width = 1;

        auto &src = srcIsX ? x : tmp;
        auto &dst = srcIsX ? tmp : x;

        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); i += static_cast<std::ptrdiff_t>(2 * width)) {
            const std::size_t left  = static_cast<std::size_t>(i);
            const std::size_t mid   = std::min(left + width, n);
            const std::size_t right = std::min(left + 2 * width, n);

            // Merge src[left:mid) and src[mid:right) into dst[left:right)
            std::size_t a = left, b = mid, out = left;
            while (a < mid && b < right) {
                if (comp(src[b], src[a])) {
                    dst[out++] = src[b++];
                } else {
                    dst[out++] = src[a++];
                }
            }
            while (a < mid)   dst[out++] = src[a++];
            while (b < right) dst[out++] = src[b++];
        }

        srcIsX = !srcIsX;
    }

    // If the final sorted data ended up in tmp, copy back to x.
    if (!srcIsX) {
        x.swap(tmp);
    }
}
